fn find_second_largest_helper(xs: List[Int], max1: Int, max2: Option[Int]) -> Option[Int]
  requires distinct(xs) and contains(xs, max1) and forall x in xs: x <= max1 and (match max2 { None => true Some(m) => m < max1 and (forall x in xs: x <= max1) })
  ensures match result { None => (len(xs) < 2) Some(v) => (contains(xs, v) and v < max1) }
  effects pure
  example find_second_largest_helper([3, 9, 1], 9, None) == Some(3)
  example find_second_largest_helper([5], 5, None) == None
{
  match xs {
    [] => max2
    [h, ..t] => 
      if h == max1 then find_second_largest_helper(t, max1, max2)
      else 
        match max2 {
          None => find_second_largest_helper(t, max1, Some(h))
          Some(m) => if h > m then find_second_largest_helper(t, max1, Some(h)) else find_second_largest_helper(t, max1, max2)
        }
  }
}

fn find_max(xs: List[Int]) -> Int
  requires len(xs) > 0
  ensures contains(xs, result) and forall x in xs: x <= result
  effects pure
  example find_max([3, 9, 1]) == 9
  example find_max([5]) == 5
  example find_max([1, 2, 3, 4, 5]) == 5
{
  match xs {
    [h, ..t] => if len(t) == 0 then h else if h > find_max(t) then h else find_max(t)
    [] => 0
  }
}

fn second_largest(xs: List[Int]) -> Option[Int]
  requires distinct(xs)
  ensures match result { None => (len(xs) < 2) Some(v) => (contains(xs, v) and (exists y in xs: ((y > v) and (forall z in xs: ((z <= v) or (z == y)))))) }
  effects pure
  example second_largest([3, 9, 1]) == Some(3)
  example second_largest([4]) == None
  example second_largest([]) == None
  example second_largest([5, 2]) == Some(2)
  example second_largest([1, 2, 3, 4, 5]) == Some(4)
{
  if len(xs) < 2 then None else find_second_largest_helper(xs, find_max(xs), None)
}

