  ensures len(result) == len(xs) - 1
  effects pure
  example remove_first([3, 9, 1], 9) == [3, 1]
  example remove_first([5, 2], 5) == [2]
  example remove_first([1, 2, 3], 1) == [2, 3]
{
  match xs {
    [] => []
    [h, ..t] => if h == val then t else [h] ++ remove_first(t, val)
  }
}

fn find_second_after_removing_max(xs: List[Int], max_elem: Int) -> Option[Int]
  requires contains(xs, max_elem) and forall x in xs: x <= max_elem and len(xs) >= 2
  ensures match result { None => not exists x in xs: x < max_elem Some(v) => contains(xs, v) and v < max_elem and forall x in xs: (x == max_elem or x <= v) }
  effects pure
  example find_second_after_removing_max([3, 9, 1], 9) == Some(3)
  example find_second_after_removing_max([1, 2], 2) == Some(1)
{
  match remove_first(xs, max_elem) {
    [] => None
    rest => Some(find_max(rest))
  }
}

fn second_largest(xs: List[Int]) -> Option[Int]
  requires distinct(xs)
  ensures match result { None => (len(xs) < 2) Some(v) => (contains(xs, v) and (exists y in xs: ((y > v) and (forall z in xs: ((z <= v) or (z == y)))))) }
  effects pure
  example (second_largest([3, 9, 1]) == Some(3))
  example (second_largest([4]) == None)
  example (second_largest([]) == None)
  example (second_largest([1, 2]) == Some(1))
  example (second_largest([5, 8, 6, 7]) == Some(7))
{
  match xs {
    [] => None
    [_, ..t] => match t { [] => None _ => find_second_after_removing_max(xs, find_max(xs)) }
  }
}

